# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: shape
def shape(xs):
    return [v for v in xs if v % 2 == 0]

# region: digest
def digest(xs, offset=-1):
    return [v + offset for v in xs]

# region: intake
def intake(xs, factor=3):
    return [v * factor for v in xs[1:]]

# region: emit
def emit(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: render
def render(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return render(emit(intake(digest(shape(gather(raw))))))

